///
/// ### Example
/// ```no_run
/// union Foo {
///     a: i32,
///     b: u32,
/// }
///
/// fn main() {
///     let _x: u32 = unsafe {
///         Foo { a: 0_i32 }.b // Undefined behavior: `b` is allowed to be padding
///     };
/// }
/// ```
/// Use instead:
/// ```no_run
/// #[repr(C)]
/// union Foo {
///     a: i32,
